const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const tierNames = { 1: 'Bronze', 2: 'Silver', 3: 'Gold', 4: 'Platinum' };
function storedJson(key){try{return JSON.parse(sessionStorage.getItem(key)||'null');}catch{return null;}}
const state = { session: null, member: null, prompts: [], admin: null, platformAdmin: false, assessment: null, assessmentStep: 0, assessmentDraft: {}, workspace: { profile: null, outputs: [], generations: [], favorites: [] }, category: 'all', importPayload: null, currentOutput: null, currentPage: 'dashboard', previewRank: null, appMode: location.pathname.startsWith('/admin') || location.pathname.startsWith('/platform') ? 'admin' : 'member', impersonation: storedJson('d9-impersonation') };

function escapeHtml(value) { const node = document.createElement('div'); node.textContent = String(value ?? ''); return node.innerHTML; }
function toast(value, error = false) { const el = $('#toast'); el.textContent = value; el.className = `toast show${error ? ' error' : ''}`; clearTimeout(toast.timer); toast.timer = setTimeout(() => el.className = 'toast', 3500); }
function message(form, value, success = false) { const el = $('[data-message]', form); if (el) { el.textContent = value || ''; el.classList.toggle('success', success); } }
function setBusy(form, busy) { $$('button', form).forEach((button) => button.disabled = busy); form?.classList.toggle('is-busy', busy); }
async function api(path, options = {}) { const headers = { ...(options.body ? { 'Content-Type': 'application/json' } : {}), ...(state.session?.access_token ? { Authorization: `Bearer ${state.session.access_token}` } : {}), ...(state.impersonation?.id ? { 'X-Impersonation-Session': state.impersonation.id } : {}), ...(state.previewRank ? { 'X-Preview-Tier': tierNames[state.previewRank] } : {}), ...(options.headers || {}) }; const result = await fetch(`/api/${path}`, { ...options, headers }); const body = await result.json().catch(() => ({})); if (!result.ok) { const error = new Error(body.error || 'Something went wrong.'); error.status = result.status; throw error; } return body; }
function saveSession(session) { state.session = session; sessionStorage.setItem('d9-platform-session', JSON.stringify(session)); }
function signOut() { state.session = state.member = state.admin = state.assessment = null; state.prompts=[]; state.workspace={profile:null,outputs:[],generations:[],favorites:[]}; state.previewRank=null; state.impersonation=null; sessionStorage.removeItem('d9-platform-session'); sessionStorage.removeItem('d9-impersonation'); $('#previewBanner').classList.add('hidden'); $('#appView').classList.add('hidden'); $('#verifyForm').classList.add('hidden'); $('#loginForm').classList.remove('hidden'); $('#authView').classList.remove('hidden'); $('#loginForm').reset(); history.replaceState({},'',state.appMode==='admin'?'/admin/login':'/login'); configureAuthScreen(); }
function showVerification() { $('#loginForm').classList.add('hidden'); $('#verifyForm').classList.remove('hidden'); $('#verifyForm [name=email]').value = state.session?.user?.email || ''; }

$('#loginForm').addEventListener('submit', async (event) => { event.preventDefault(); const form = event.currentTarget; message(form, ''); setBusy(form, true); try { saveSession(await api('auth-session', { method: 'POST', body: JSON.stringify(Object.fromEntries(new FormData(form))) })); await enterApp(); } catch (error) { message(form, error.message); } finally { setBusy(form, false); } });
$('#verifyForm').addEventListener('submit', async (event) => { event.preventDefault(); const form = event.currentTarget; message(form, ''); setBusy(form, true); try { await api('member-eligibility', { method: 'POST', body: JSON.stringify(Object.fromEntries(new FormData(form))) }); await enterApp(); } catch (error) { message(form, error.message); } finally { setBusy(form, false); } });

async function enterApp() {
  try {
    if (state.appMode === 'admin') {
      try {
        state.admin = await api('admin-console');
        const account=state.admin.admin.account;
        state.platformAdmin=state.admin.admin.roles?.includes('platform_admin')||state.admin.admin.roles?.includes('super_admin'); showApp(); toggleMemberNav(false); configureAdminView(); configurePlatformView();
        setIdentity(account, account.account_designation || 'D9Network Administrator');
        $('#workspaceEyebrow').textContent='D9Network administration';
        if(state.impersonation){$('#previewMessage').textContent=`Viewing as ${state.impersonation.target_name || 'selected account'} · ${state.impersonation.viewed_role.replaceAll('_',' ')}${state.impersonation.simulated_tier?` · ${state.impersonation.simulated_tier}`:''} · Read only`;$('#previewBanner').classList.remove('hidden');}
        renderAdmin();
        const requested=pageFromPath(), destination=requested.page==='import'&&state.admin.admin.permissions.data?'import':'admin', requestedTab=location.pathname==='/admin/login'?null:requested.tab, selectedTab=adminTabAllowed(requestedTab)?requestedTab:firstAdminTab();
        state.adminTab=selectedTab;
        go(destination,false); showAdminTab(selectedTab); if(destination==='admin'&&(!requestedTab||requestedTab!==selectedTab))history.replaceState({page:'admin'},'',adminTabPath(selectedTab)); return;
      } catch (adminError) {
        if (adminError.status !== 403) throw adminError;
        state.appMode='member'; history.replaceState({accessDenied:true},'', '/dashboard?access-denied=1'); toast('You do not have permission to access Administration.',true);
      }
    }
    let data;
    try { data = await api('prompts-list'); }
    catch (memberError) { if (memberError.status === 403) { showVerification(); return; } throw memberError; }
    state.platformAdmin=Boolean(data.platform_admin); if(state.platformAdmin&&!state.admin){try{state.admin=await api('admin-console');}catch{}} state.member = data.member; state.prompts = data.prompts || []; showApp(); toggleMemberNav(true); configurePlatformView(); renderMember();
    try { state.workspace = await api('member-workspace'); } catch { state.workspace = { profile: null, outputs: [], generations: [], favorites: [] }; }
    try { state.assessment = await api('assessment'); } catch { state.assessment = null; }
    renderAllMemberViews(); go('dashboard',false);
    const requested=pageFromPath(); if(requested.page!=='dashboard'||location.pathname==='/dashboard') { if(requested.tab)state.adminTab=requested.tab; go(requested.page,false); if(requested.tab)showAdminTab(requested.tab); }
  } catch (error) { if (error.status === 403) return showVerification(); if (error.status === 401) return signOut(); toast(error.message, true); }
}
function showApp() { $('#authView').classList.add('hidden'); $('#appView').classList.remove('hidden'); }
function toggleMemberNav(show) { $('#memberNavLabel').classList.toggle('hidden',!show); $$('[data-page="dashboard"],.nav-group:not(.admin-group)').forEach((item) => item.classList.toggle('hidden', !show)); $('#adminNav').classList.toggle('hidden',!state.admin); $('.feedback-trigger').classList.toggle('hidden',!show); }
function configureAdminView() { const permissions=state.admin?.admin?.permissions||{}; $('#adminNav').classList.remove('hidden'); $$('[data-admin-role]').forEach((item)=>item.classList.toggle('hidden',!permissions[item.dataset.adminRole])); const dashboard=$('#adminNav [data-admin-tab="dashboard"]'); if(dashboard)dashboard.classList.toggle('hidden',!permissions.dashboard); }
function configurePlatformView(){const control=$('#platformViewControl'),select=$('#platformView');control.classList.toggle('hidden',!state.platformAdmin);if(!state.platformAdmin)return;select.value=state.appMode==='admin'?'platform':(state.previewRank?tierNames[state.previewRank]:'member');if(state.appMode==='member'){$('#previewMessage').textContent=state.previewRank?`Previewing the ${tierNames[state.previewRank]} member experience. Your role and membership are unchanged.`:'Member View for platform testing. Your role and membership are unchanged.';$('#previewBanner').classList.remove('hidden');}}
function initials(profile){return [profile?.first_name,profile?.last_name].filter(Boolean).map((part)=>String(part).trim()[0]).join('').toUpperCase();}
function setIdentity(profile, designation) { const name=[profile?.first_name,profile?.last_name].filter(Boolean).join(' '); $('#memberName').textContent=name; $('#memberTier').textContent=designation||''; $('#tierBadge').textContent=designation||''; $('#avatar').textContent=initials(profile); }
function renderMember() { const first=String(state.member.first_name||'').trim(), tier=state.member.growth_kit_tier||''; setIdentity(state.member,tier?`${tier} member`:''); $('#dashboardWelcome').textContent=first?`Welcome Back, ${first}`:'Welcome Back'; }
function categoryOf(prompt) { return prompt.prompt_categories || { id: 'general', name: 'General', slug: 'general' }; }
function favoriteIds() { return new Set((state.workspace.favorites || []).map((item) => item.prompt_id)); }
function effectiveRank(){return Number(state.previewRank||state.member?.growth_kit_tier_rank||0)}
