function assessmentStats(){const questions=state.assessment?.questions||[],answered=questions.filter((question)=>state.assessmentDraft[question.id]).length;return{answered,total:questions.length,percent:questions.length?Math.round(answered/questions.length*100):0};}
function refreshAssessmentProgress(){const stats=assessmentStats(),sections=state.assessment?.sections||[];const percent=$('#assessmentProgress b'),bar=$('#assessmentProgress .progress-track span');if(percent)percent.textContent=`${stats.percent}% Complete`;if(bar)bar.style.width=`${stats.percent}%`;$('#assessmentOverview').innerHTML=sections.map(assessmentSectionCard).join('');}
