function profileSummary(){const p=state.workspace.profile;if(!p)return'';const labels={business_name:'Business',industry:'Industry',other_industry_name:'Other Industry Name',business_description:'Description',products:'Products',services:'Services',website:'Website',years_in_business:'Years in Business',target_market:'Target Market',ideal_customer:'Ideal Customers',business_goals:'Business Goals',business_stage:'Business Stage',geographic_market:'Geographic Market',primary_markets_served:'Primary Markets Served',markets_to_enter:'Markets You Want to Enter',primary_business_challenges:'Primary Business Challenges',other_business_challenge:'Other Business Challenge',business_certifications:'Business Certifications & Designations',other_certification_name:'Other Certification Name',interested_in_certifications:'Interested in Obtaining Certifications',social_linkedin:'LinkedIn',social_facebook:'Facebook',social_instagram:'Instagram',social_x:'X',social_other:'Other Social Link'};return Object.entries(labels).filter(([key])=>Array.isArray(p[key])?p[key].length:p[key]).map(([key,label])=>`${label}: ${Array.isArray(p[key])?p[key].join(', '):p[key]}`).join('\n');}
function profileContext(override) { const value=String(override||profileSummary()).trim(); return value ? `Use this reviewed business profile as context. Do not claim an action was taken or an outcome achieved unless the member explicitly provides evidence.\n${value}\n\n` : ''; }
function questionSchema(prompt) { const questions = [...(prompt.prompt_questions || [])].sort((a,b) => a.sort_order - b.sort_order); return questions.length ? questions.map((q) => ({ key:q.field_key,label:q.label,type:q.field_type })) : (prompt.form_schema || []); }
function openTool(id) { const prompt = state.prompts.find((item) => item.id === id); if (!prompt) return; const schema = questionSchema(prompt); $('#workspace').innerHTML = `<div class="workspace"><form id="builderForm" class="panel"><p class="eyebrow">${escapeHtml(categoryOf(prompt).name)}</p><h3>${escapeHtml(prompt.title)}</h3><p class="muted">${escapeHtml(prompt.description)}</p><div class="profile-context"><b>Personalized with your Business Profile</b><span>${profileComplete() ? 'Saved context will be included automatically.' : 'Complete your profile for stronger recommendations.'}</span></div>${schema.map((field,index) => `<div class="question"><label for="answer-${index}">${escapeHtml(field.label || `Question ${index + 1}`)}</label>${field.type === 'text' ? `<input id="answer-${index}" name="${escapeHtml(field.key)}" required>` : `<textarea id="answer-${index}" name="${escapeHtml(field.key)}" required></textarea>`}</div>`).join('')}<div class="workspace-actions"><button class="button primary" type="submit">Generate Strategy</button><button id="clearBuilder" class="button subtle" type="button">Clear</button></div></form><div><div class="panel"><p class="eyebrow">Business Growth Recommendations</p><h3>Your strategy workspace</h3><p class="muted">Complete the guided questions to prepare tailored recommendations.</p><div id="promptOutput" class="output">Your recommendations will appear here.</div><div class="workspace-actions"><button id="copyPrompt" class="button subtle" type="button">Copy</button><button id="saveOutput" class="button primary" type="button" disabled>Save Strategy</button></div></div><div class="market-callout"><small>Future Marketplace capability</small><h4>${escapeHtml(categoryOf(prompt).name)} Agent</h4><p>${escapeHtml(prompt.marketplace_upgrade_message || 'Connect saved business context, automation, and ongoing recommendations in a future D9Network Marketplace capability.')}</p></div></div></div>`; const form = $('#builderForm'); form.addEventListener('submit', async (event) => { event.preventDefault(); setBusy(form, true); const answers = Object.fromEntries(new FormData(form)); $('#promptOutput').innerHTML = '<span class="generating"><i></i>Generating your strategy context…</span>'; await new Promise((resolve) => setTimeout(resolve, 450)); let output = prompt.user_prompt_template; Object.entries(answers).forEach(([key,value]) => output = output.replaceAll(`{{${key}}}`, value)); output = `${profileContext()}${output}\n\nRequired output format: ${prompt.output_format || 'Provide clear, prioritized recommendations with next steps.'}`; state.currentOutput = { prompt_id: prompt.id, title: prompt.title, input_payload: answers, output_text: output }; $('#promptOutput').textContent = output; $('#saveOutput').disabled = false; setBusy(form, false); try { await api('member-workspace', { method:'POST', body:JSON.stringify({ action:'record_generation', ...state.currentOutput }) }); await reloadWorkspace(); } catch {} }); go('workspace'); }

