  const form=$('#builderForm');
  form.addEventListener('submit',async(event)=>{event.preventDefault();setBusy(form,true);const answers=Object.fromEntries(new FormData(form)),context=answers.profile_override;delete answers.profile_override;$('#promptOutput').innerHTML='<span class="generating"><i></i>Generating your strategy context…</span>';await new Promise((resolve)=>setTimeout(resolve,450));let output=prompt.user_prompt_template;Object.entries(answers).forEach(([key,value])=>output=output.replaceAll(`{{${key}}}`,value));output=`${profileContext(context)}${output}\n\nRequired output format: ${prompt.output_format||'Provide clear, prioritized recommendations with next steps.'}`;state.currentOutput={prompt_id:prompt.id,title:prompt.title,input_payload:{...answers,profile_context:context},output_text:output};$('#promptOutput').textContent=output;$('#saveOutput').disabled=false;setBusy(form,false);try{await api('member-workspace',{method:'POST',body:JSON.stringify({action:'record_generation',...state.currentOutput})});await reloadWorkspace();}catch{}});
  go('workspace');
