openTool=openToolV2;

function assemblePersonalizedPrompt(prompt,context,answers){let task=String(prompt.user_prompt_template||'').trim();Object.entries(answers).forEach(([key,value])=>task=task.replaceAll(`{{${key}}}`,String(value).trim()));const responses=Object.entries(answers).map(([key,value])=>`${key.replaceAll('_',' ')}: ${String(value).trim()}`).join('\n');return [String(prompt.system_prompt||'').trim(),profileContext(context).trim(),responses?`Guided Responses:\n${responses}`:'',`Task:\n${task}`,`Desired Output:\n${prompt.output_format||'Provide clear, prioritized recommendations with practical next steps.'}`].filter(Boolean).join('\n\n');}
