function editorData(prompt = {}) { const form = $('#editorForm'); form.reset(); const fields = ['id','title','slug','description','user_prompt_template','output_format','marketplace_upgrade_message','estimated_minutes','status']; fields.forEach((key) => { if (form.elements[key]) form.elements[key].value = prompt[key] ?? (key === 'status' ? 'draft' : ''); }); form.elements.minimum_tier.value = tierNames[prompt.minimum_tier_rank] || 'Bronze'; form.elements.category_id.innerHTML = (state.admin.categories || []).map((c) => `<option value="${c.id}">${escapeHtml(c.name)}</option>`).join(''); if (prompt.category_id) form.elements.category_id.value = prompt.category_id; form.elements.questions.value = (prompt.form_schema || []).map((q) => `${q.key}|${q.label}`).join('\n'); form.elements.is_featured.checked = Boolean(prompt.is_featured); $('#deletePrompt').classList.toggle('hidden', !prompt.id); $('#editorTitle').textContent = prompt.id ? 'Edit Business Growth Tool' : 'New Business Growth Tool'; $('#editorDialog').showModal(); }
