$('#assessmentForm').addEventListener('submit',async(e)=>{e.preventDefault();const form=e.currentTarget,stats=assessmentStats();if(stats.answered!==stats.total){message(form,'Complete every assessment section before submitting.');return;}setBusy(form,true);message(form,'');try{const answers={...state.assessmentDraft},data=await api('assessment',{method:'POST',body:JSON.stringify({action:'complete',answers})});state.assessment.latest={response:{completed_at:data.completed_at,answers},result:data.result,recommendations:data.result.recommendations};renderAssessment();renderDashboard();renderBusinessGuidance();toast(data.preview?'Assessment saved to your administrator test workspace.':'Business Growth Assessment completed.');$('#assessmentResults').scrollIntoView({behavior:'smooth'});}catch(err){message(form,err.message);}finally{setBusy(form,false);}});
