$('#assessmentAdmin').addEventListener('click',async(e)=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.questionActive)await api('admin-console',{method:'POST',body:JSON.stringify({action:'save_assessment_question',question:{id:button.dataset.questionActive,is_active:button.dataset.active==='true'}})});else if(button.dataset.sectionActive)await api('admin-console',{method:'POST',body:JSON.stringify({action:'save_assessment_section',section:{id:button.dataset.sectionActive,is_active:button.dataset.active==='true'}})});else if(button.dataset.mappingActive)await api('admin-console',{method:'POST',body:JSON.stringify({action:'save_assessment_mapping',mapping:{id:button.dataset.mappingActive,is_active:button.dataset.active==='true'}})});else if(button.dataset.addQuestion){const text=window.prompt('Enter the new assessment question.');if(!text)return;await api('admin-console',{method:'POST',body:JSON.stringify({action:'save_assessment_question',question:{section_id:button.dataset.addQuestion,question_text:text,answer_type:'yes_partial_no_na',display_order:100,is_active:true}})});}else if(button.dataset.addMapping){const select=$(`[data-mapping-tool="${button.dataset.addMapping}"]`);if(!select.value)return toast('Select a Business Growth Tool first.',true);await api('admin-console',{method:'POST',body:JSON.stringify({action:'save_assessment_mapping',mapping:{section_id:button.dataset.addMapping,prompt_id:select.value,priority:100,is_active:true}})});}else if(button.dataset.addSection){const title=window.prompt('Enter the new assessment section title.');if(!title)return;const version=state.admin.assessment.versions.find((item)=>item.is_active)||state.admin.assessment.versions[0];await api('admin-console',{method:'POST',body:JSON.stringify({action:'save_assessment_section',section:{version_id:version.id,title,slug:title.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''),display_order:999,is_active:true}})});}else return;await reloadAdmin();toast('Assessment configuration updated.');});
document.addEventListener('submit',async(e)=>{if(e.target.id!=='impersonationForm')return;e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form));setBusy(form,true);try{const result=await api('admin-console',{method:'POST',body:JSON.stringify({action:'start_impersonation',...data})});state.impersonation=result.session;sessionStorage.setItem('d9-impersonation',JSON.stringify(result.session));$('#previewMessage').textContent=`Viewing as ${result.session.target_name || 'selected account'} · ${result.session.viewed_role.replaceAll('_',' ')}${result.session.simulated_tier?` · ${result.session.simulated_tier}`:''} · Read only`;$('#previewBanner').classList.remove('hidden');toast('Audited view-as-user session started.');}catch(error){message(form,error.message);}finally{setBusy(form,false);}});
function fileToBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});}

document.addEventListener('click',(event)=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.guidanceToggle!==undefined){event.preventDefault();try{localStorage.setItem('d9-growth-guidance-collapsed',String(!guidancePreference()));}catch{}renderBusinessGuidance();}if(button.dataset.dismissProfileNext!==undefined)$('#profileSaveNextStep').classList.add('hidden');});
document.addEventListener('click',(event)=>{const button=event.target.closest('button');if(button?.id!=='clearBuilder'||$('#saveOutput'))return;event.preventDefault();event.stopImmediatePropagation();$('#builderForm')?.reset();const output=$('#promptOutput');if(output)output.textContent='Your personalized prompt will appear here.';const copy=$('#copyBuiltPrompt'),used=$('#markToolUsed');if(copy)copy.disabled=true;if(used)used.disabled=true;state.currentOutput=null;},true);

